// Nodes utilities - extracted from Nodes.tsx

import type { Node } from '@/shared/types/node';
import type { StateStyle } from '../types/nodes';
import { STATE_STYLES, DRIVER_ARCS } from '../types/nodes';

export function resolveState(n: Node): Node['state'] & string {
  if (n.state) return n.state;
  return n.status === 'up' ? 'up' : 'down';
}

export function isLocalAddress(addr: string): boolean {
  try {
    const url = new URL(`http://${addr}`);
    const host = url.hostname;
    return (
      host === '127.0.0.1' ||
      host === 'localhost' ||
      host === '::1' ||
      host === '[::1]' ||
      host.startsWith('127.')
    );
  } catch {
    return (
      addr.startsWith('127.0.0.1:') ||
      addr.startsWith('127.0.0.1') ||
      addr.startsWith('localhost:') ||
      addr.startsWith('localhost') ||
      addr.startsWith('[::1]:') ||
      addr.startsWith('::1')
    );
  }
}

export function formatBytes(bytes: number): string {
  if (!bytes || bytes <= 0 || !Number.isFinite(bytes)) return '0 MB';
  if (bytes < 1024 ** 2) return `${Math.round(bytes / 1024)} KB`;
  if (bytes < 1024 ** 3) return `${Math.round(bytes / 1024 ** 2)} MB`;
  const gb = bytes / 1024 ** 3;
  if (gb < 1024) return gb >= 10 ? `${gb.toFixed(1)}GB` : `${gb.toFixed(2)}GB`;
  const tb = gb / 1024;
  return tb >= 10 ? `${tb.toFixed(1)}TB` : `${tb.toFixed(2)}TB`;
}

export function formatBytesPair(used: number, total: number): string {
  if (!total || total <= 0 || !Number.isFinite(total)) {
    return used > 0 ? `${formatBytes(used)} / —` : '— / —';
  }
  return `${formatBytes(used)} / ${formatBytes(total)}`;
}

export function formatPercent(pct: number): string {
  if (!Number.isFinite(pct)) return '0%';
  return `${pct.toFixed(pct >= 10 ? 0 : 1)}%`;
}

export function withAlpha(color: string, alpha: number): string {
  const c = color.trim();
  if (!c) return c;
  const hexMatch = c.match(/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})([0-9a-fA-F]{2})?$/);
  if (hexMatch) {
    let h = hexMatch[1];
    if (h.length === 3) h = h.split('').map((x) => x + x).join('');
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b = parseInt(h.slice(4, 6), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  }
  const rgbMatch = c.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/);
  if (rgbMatch) return `rgba(${rgbMatch[1]}, ${rgbMatch[2]}, ${rgbMatch[3]}, ${alpha})`;
  return c;
}

export function buildMonitor(n: Node, hbMap: Record<number, any[]>): ('up' | 'down')[] {
  const hbs = hbMap[n.id] || [];
  const out: ('up' | 'down')[] = [];
  for (let i = 0; i < 40; i++) {
    if (i < hbs.length) {
      out.push(hbs[i].status === 'up' ? 'up' : 'down');
    } else {
      out.push(n.status === 'up' ? 'up' : 'down');
    }
  }
  return out;
}

export function buildEdgeConfig(
  name: string,
  address: string,
  useTls: boolean,
  token: string,
  opts?: {
    connectionMode?: string;
    port?: string | number;
    skipVerify?: boolean;
    instancesDir?: string;
  },
): string {
  const origin = typeof window !== 'undefined' ? window.location.origin : 'http://localhost:5050';
  // Derive the edge listen port from the explicit opt first, then from the
  // node address (host:port), falling back to 4040 for bare hosts / tunnel.
  let listenPort = 4040;
  if (opts?.port !== undefined && opts.port !== '') {
    const n = Number(opts.port);
    if (Number.isFinite(n) && n > 0) listenPort = n;
  } else {
    const m = String(address || '').match(/:(\d+)\s*$/);
    if (m) {
      const n = Number(m[1]);
      if (Number.isFinite(n) && n > 0 && n <= 65535) listenPort = n;
    }
  }
  const upstreamTls = origin.trim().toLowerCase().startsWith('https');
  void useTls;
  // Flat scalar schema only — emit YAML directly (no dep): plain `key: value`
  // lines, strings double-quoted via JSON.stringify (valid YAML for this
  // value domain). Key order matches the edge's config.Load.
  const lines: string[] = ['# ksedge edge config (YAML) — place next to the ksedge binary'];
  const str = (v: unknown): string => JSON.stringify(String(v ?? ''));
  lines.push(`uuid: ${str('auto-generated-by-panel')}`);
  lines.push(`name: ${str(name)}`);
  lines.push(`panel_url: ${str(origin)}`);
  lines.push(`token: ${str(token)}`);
  lines.push(`listen_port: ${listenPort}`);
  lines.push(`heartbeat_interval: 60`);
  lines.push(`use_tls_upstream: ${upstreamTls ? 'true' : 'false'}`);
  lines.push(`skip_verify: ${Boolean(opts?.skipVerify) ? 'true' : 'false'}`);
  if (opts?.instancesDir && String(opts.instancesDir).trim()) {
    lines.push(`instances_dir: ${str(String(opts.instancesDir).trim())}`);
  }
  lines.push(`connection_mode: ${str((opts?.connectionMode || 'direct') as string)}`);
  return lines.join('\n') + '\n';
}